// Code generated by hydrogo generator; bounded CSV helpers.
export const ArticleImportLimits = { maxBytes: 5 * 1024 * 1024, maxRows: 5000 } as const;

function csvCell(value: unknown): string {
  const text = String(value ?? '');
  return /[",\r\n]/.test(text) ? '"' + text.replace(/"/g, '""') + '"' : text;
}

export function ArticleExportCSV(rows: Record<string, unknown>[], columns: string[]): string {
  if (rows.length > ArticleImportLimits.maxRows) throw new Error('export row limit exceeded');
  return [columns.map(csvCell).join(','), ...rows.map(row => columns.map(column => csvCell(row[column])).join(','))].join('\n');
}

export function ArticleValidateImport(payload: string): void {
  if (new TextEncoder().encode(payload).byteLength > ArticleImportLimits.maxBytes) throw new Error('import payload limit exceeded');
  if (payload.split(/\r?\n/).filter(Boolean).length > ArticleImportLimits.maxRows + 1) throw new Error('import row limit exceeded');
}
